=Here is the Business Requirement Document and the user stories derived from it.
Select the estimation panel.

# Business Requirement Document
{{ $('Webhook Intake').item.json.body.summary }}


# Project Context
{{ $json.output[0].content[0].text.project_context }}

# User Stories ({{ $json.output[0].content[0].text.stories.length }})
{{ $json.output[0].content[0].text.stories.map((s, i) => `${i+1}. [${s.domain}] ${s.user_story}`).join('\n') }}

textOptions.schema:
{
  "type": "object",
  "properties": {
    "dimensionFilters": {
      "type": "object",
      "properties": {
        "dev_role_archetype": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": ["Front-end developer", "Back-end developer", "Full-stack developer", "Mobile developer", "Data / ML developer", "DevOps / SRE / infrastructure", "Security engineer", "Game developer", "Embedded / systems developer", "Engineering manager / lead", "Product / UX technical role"]
          }
        },
        "dev_professional_status": {
          "type": "array",
          "items": { "type": "string", "enum": ["Professional developer"] }
        }
      },
      "additionalProperties": false,
      "required": ["dev_role_archetype", "dev_professional_status"]
    },
    "sampleSize": { "type": "integer" },
    "rationale": { "type": "string" }
  },
  "additionalProperties": false,
  "required": ["dimensionFilters", "sampleSize", "rationale"]
}

