// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const po = $('Agile PO').first().json.output[0].content[0].text;
return po.stories.map(s => ({
  json: { ...s, projectContext: po.project_context }
}));

const results = $input.all().map(i => i.json);
return [{
  json: {
    summary: "SOW Estimation Complete",
    full_backlog: results
  }
}];

const CONFIG = {
  baseUrl: "https://debug-celebrate-shade-hero.trycloudflare.com",
  personaPool: "persona/datasets/matraix-persona-dev-sample"
};

return $input.all().map(item => ({
  json: { ...item.json, ...CONFIG }
}));

